// =============================================================================
// MUNICIPIOS DE ESPAÑA — código INE y denominación oficial.
// Generado por script (feature-9); NO editar a mano.
//
// POR QUÉ EXISTE: el municipio del expediente es una CLAVE de cruce con las
// tablas normativas que clasifican POR MUNICIPIO (zona de radón del DB-HS6
// Apéndice B, aceleración sísmica NCSE-02, pluviometría…), no una etiqueta.
// Escrito a mano no serviría: "Vitoria", "Vitoria-Gasteiz" y "Gasteiz" serían
// tres municipios distintos. La clave estable es el CÓDIGO INE.
//
// PROCEDENCIA (fuente OFICIAL):
//   Instituto Nacional de Estadística — "Municipios por provincia con sus
//   códigos": https://www.ine.es/daco/daco42/codmun/26codmun.xlsx
//   Relación de municipios a 01-01-2026. Descargado y transcrito el 2026-08-23
//   leyendo el XLSX directamente (52 hojas, una por provincia; columnas
//   CPRO + CMUN + DC + NOMBRE). El código INE de 5 dígitos es CPRO+CMUN; el
//   dígito de control (DC) se descarta. Total: 8132 municipios, 52 provincias.
//
//   Transcripción literal salvo dos normalizaciones de PRESENTACIÓN:
//     · el artículo pospuesto del INE se antepone ("Iglesuela del Cid, La" →
//       "La Iglesuela del Cid"); el orden alfabético se aplica después;
//     · las denominaciones bilingües se conservan íntegras, sin partir
//       ("Donostia/San Sebastián", "Vitoria-Gasteiz").
//
// SIN ALTITUD, Y ES DELIBERADO: se evaluó incorporar la altitud por municipio
// (Wikidata P2044, cruzada por P772) para autocompletar el campo del que
// depende la zona climática. Se DESCARTÓ tras contrastarla: la fuente mezcla
// criterios sin distinguirlos — da 2.123 m para Aller (cota del pico del
// concejo; su núcleo está a ~500 m) y 0 m para Ferrol o Siero — y sobre las
// capitales se desviaba hasta 78 m (Toledo 523 vs 445 m), suficiente para
// cruzar un tramo de la Tabla a-Anejo B y cambiar el U_lim exigido al edificio.
// La altitud del núcleo de las 52 CAPITALES sí está, verificada, en
// ./zonasClimaticasHE.ts ('altitudCapital_m'), y es la que la UI sugiere.
// =============================================================================

/** Un municipio con su clave INE oficial. */
export interface MunicipioINE {
  /** Código INE de 5 dígitos: 2 de provincia + 3 de municipio. Clave estable. */
  ine: string;
  /** Denominación oficial (artículo antepuesto para presentación). */
  nombre: string;
}

/** Expande la forma compacta del literal (el archivo pesa ~40 % menos así). */
function desempaquetar(xs: readonly { i: string; n: string }[]): readonly MunicipioINE[] {
  return xs.map((x) => ({ ine: x.i, nombre: x.n }));
}

