/** Busca un municipio por su código INE. `null` si no existe. */
export function buscarMunicipioPorIne(
  ine: string,
): { provincia: string; municipio: MunicipioINE } | null {
  for (const [provincia, lista] of Object.entries(MUNICIPIOS_POR_PROVINCIA)) {
    const municipio = lista.find((m) => m.ine === ine);
    if (municipio !== undefined) return { provincia, municipio };
  }
  return null;
}
